export const LANDING_SCRIPT = String.raw`
(function(){
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* ---- marquee ---- */
  var phrases = ['Death to the Doxer','Find the Spot','Where is this?','Spot Found','Unknown Location','Coastal Intelligence','Mission Active'];
  var track = document.getElementById('track');
  if(track){
    function build(){
      var frag='';
      phrases.forEach(function(p){ frag += '<span class="item">'+p+'<span class="x">✛</span></span>'; });
      return frag;
    }
    track.innerHTML = build()+build();
  }

  /* ---- live clock + coordinate jitter ---- */
  var baseLat = 37.0106, baseLng = -8.9502;
  function pad(n){return (n<10?'0':'')+n;}
  function tick(){
    var d=new Date();
    var z = pad(d.getUTCHours())+':'+pad(d.getUTCMinutes())+':'+pad(d.getUTCSeconds())+'Z';
    var jLat=(baseLat + (Math.random()-0.5)*0.0006).toFixed(4);
    var jLng=(Math.abs(baseLng) + (Math.random()-0.5)*0.0006).toFixed(4);
    var coord = jLat+'°N '+jLng+'°W';
    var tc=document.getElementById('topclock'); if(tc) tc.textContent = coord+' · '+z;
    var gr=document.getElementById('gridref'); if(gr) gr.textContent = coord;
    var fc=document.getElementById('footclock'); if(fc) fc.textContent = z;
  }
  tick(); setInterval(tick, reduce?4000:1000);

  /* ---- pin drop-in stagger ---- */
  if(!reduce){
    document.querySelectorAll('[data-drop]').forEach(function(el){
      var n = parseInt(el.getAttribute('data-drop'),10)||1;
      el.style.opacity='0';
      setTimeout(function(){
        el.style.transition='opacity .5s ease, transform .5s cubic-bezier(.2,.7,.3,1)';
        el.style.opacity='1';
      }, 500 + n*140);
    });
  }

  /* ---- Pass A→B connector lines in mini diagram ---- */
  /* draw faint lines from each A to converged center for illustration */
  function lineBetween(container, x1p,y1p,x2p,y2p){
    var el=document.createElement('div');
    el.style.position='absolute'; el.style.zIndex='1';
    var rect=container.getBoundingClientRect();
    var x1=x1p/100*rect.width, y1=y1p/100*rect.height, x2=x2p/100*rect.width, y2=y2p/100*rect.height;
    var dx=x2-x1, dy=y2-y1, len=Math.sqrt(dx*dx+dy*dy), ang=Math.atan2(dy,dx)*180/Math.PI;
    el.style.left=x1p+'%'; el.style.top=y1p+'%'; el.style.width=len+'px'; el.style.height='1px';
    el.style.background='linear-gradient(90deg,rgba(232,226,212,.35),rgba(228,19,15,.5))';
    el.style.transformOrigin='left center'; el.style.transform='rotate('+ang+'deg)';
    container.appendChild(el);
  }
  var mb=document.getElementById('miniB');

  /* ---- reveal on scroll (with hard fallback so content can never stay hidden) ---- */
  var revealEls = [].slice.call(document.querySelectorAll('.reveal'));
  function revealAll(){ revealEls.forEach(function(el){ el.classList.add('in'); }); }
  if(reduce || !('IntersectionObserver' in window)){
    revealAll();
  } else {
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); } });
    }, {threshold:0.1, rootMargin:'0px 0px -6% 0px'});
    revealEls.forEach(function(el){ io.observe(el); });
    /* safety net: if anything is still hidden but already within the document flow after load, show it */
    window.addEventListener('load', function(){ setTimeout(function(){
      revealEls.forEach(function(el){
        var r = el.getBoundingClientRect();
        if(r.top < window.innerHeight*1.1) el.classList.add('in');
      });
    }, 400); });
  }

})();
`;
